// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {CVXStaker, ICVXBooster, IERC20} from "../src/CVXStaker.sol";

contract InvMutTest is Test {
    CVXStaker c;
    function setUp() public { c = new CVXStaker(address(new __InvMutHandleStub()), IERC20(address(this)), ICVXBooster(address(this)), new address[](0)); }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        // owner (deployer = test contract) sets the rewards recipient
        vm.prank(address(this));
        c.setRewardsRecipient(recipient);
        // general rule: after a successful owner call with argument r,
        // the stored recipient equals r
        assertTrue(c.rewardsRecipient() == recipient, "rewardsRecipient must be set to the requested recipient");
    }
}
